<script setup lang="ts">
import { Link, useForm } from '@inertiajs/vue3';
import type { Doctor, Specialty } from '@/types';
const props=defineProps<{doctor?:Doctor;specialties:Specialty[]}>();
const selectedIds=props.doctor?.specialties?.map(item=>item.id)??[];
const primary=props.doctor?.specialties?.find(item=>item.pivot?.is_primary)?.id??'';
const form=useForm({first_name:props.doctor?.first_name??'',last_name:props.doctor?.last_name??'',professional_name:props.doctor?.professional_name??'',credential_type:props.doctor?.credential_type??'',credential_number:props.doctor?.credential_number??'',email:props.doctor?.email??'',phone:props.doctor?.phone??'',biography:props.doctor?.biography??'',schedules:(props.doctor?.schedules??[]).map(String),specialty_ids:selectedIds,primary_specialty_id:primary,is_active:props.doctor?.is_active??true,is_public:props.doctor?.is_public??true,signature:null as File|null,seal:null as File|null});
let schedules=form.schedules.join('\n');
const file=(event:Event,key:'signature'|'seal')=>form[key]=(event.target as HTMLInputElement).files?.[0]??null;
const submit=()=>{form.schedules=schedules.split('\n').map(v=>v.trim()).filter(Boolean);if(!form.specialty_ids.includes(form.primary_specialty_id))form.primary_specialty_id='';props.doctor?form.transform(data=>({...data,_method:'put'})).post(route('admin.doctors.update',props.doctor.id),{forceFormData:true,preserveScroll:true}):form.post(route('admin.doctors.store'),{forceFormData:true});};
</script>
<template><form class="panel form-panel" @submit.prevent="submit"><div class="form-grid"><div class="field"><label for="first-name">Nombres</label><input id="first-name" v-model="form.first_name" required maxlength="255"><span class="field-error">{{ form.errors.first_name }}</span></div><div class="field"><label for="last-name">Apellidos</label><input id="last-name" v-model="form.last_name" required maxlength="255"><span class="field-error">{{ form.errors.last_name }}</span></div><div class="field"><label for="professional-name">Nombre profesional</label><input id="professional-name" v-model="form.professional_name" maxlength="255"><span class="field-error">{{ form.errors.professional_name }}</span></div><div class="field"><label for="email">Correo</label><input id="email" v-model="form.email" type="email" maxlength="255"><span class="field-error">{{ form.errors.email }}</span></div><div class="field"><label for="credential-type">Tipo de credencial</label><input id="credential-type" v-model="form.credential_type" maxlength="50" placeholder="Ej. CMP"><span class="field-error">{{ form.errors.credential_type }}</span></div><div class="field"><label for="credential-number">Número de credencial</label><input id="credential-number" v-model="form.credential_number" maxlength="100"><span class="field-error">{{ form.errors.credential_number }}</span></div><div class="field"><label for="phone">Teléfono</label><input id="phone" v-model="form.phone" maxlength="40"><span class="field-error">{{ form.errors.phone }}</span></div><div class="field field--wide"><label for="biography">Biografía</label><textarea id="biography" v-model="form.biography" maxlength="20000" rows="7"></textarea><span class="field-error">{{ form.errors.biography }}</span></div><div class="field field--wide"><label for="schedules">Horarios <i>uno por línea</i></label><textarea id="schedules" v-model="schedules" rows="4" placeholder="Lunes 09:00-13:00"></textarea><span class="field-error">{{ form.errors.schedules }}</span></div></div><fieldset class="form-fieldset"><legend>Especialidades</legend><div class="choice-grid"><label v-for="item in specialties" :key="item.id"><input v-model="form.specialty_ids" type="checkbox" :value="item.id"> {{ item.name }}</label></div><span class="field-error">{{ form.errors.specialty_ids }}</span><div class="field"><label for="primary-specialty">Especialidad principal</label><select id="primary-specialty" v-model="form.primary_specialty_id"><option value="">Sin principal</option><option v-for="item in specialties.filter(s=>form.specialty_ids.includes(s.id))" :key="item.id" :value="item.id">{{ item.name }}</option></select><span class="field-error">{{ form.errors.primary_specialty_id }}</span></div></fieldset><fieldset class="form-fieldset private-assets"><legend>Activos privados de emisión</legend><p class="privacy-text">La firma y el sello se almacenan en espacio privado, no se publican y solo se sirven mediante rutas autenticadas y autorizadas.</p><div class="form-grid"><div class="field"><label for="signature">Firma privada <i>JPG, PNG o WebP; máx. 2 MB</i></label><input id="signature" type="file" accept="image/jpeg,image/png,image/webp" @change="file($event,'signature')"><span class="field-error">{{ form.errors.signature }}</span></div><div class="field"><label for="seal">Sello privado <i>JPG, PNG o WebP; máx. 2 MB</i></label><input id="seal" type="file" accept="image/jpeg,image/png,image/webp" @change="file($event,'seal')"><span class="field-error">{{ form.errors.seal }}</span></div></div></fieldset><div v-if="doctor?.photo_path" class="privacy-text">Foto pública configurada: <code>{{ doctor.photo_path }}</code>. Este endpoint no permite modificarla.</div><div class="check-row"><label><input v-model="form.is_active" type="checkbox"> Activo</label><label><input v-model="form.is_public" type="checkbox"> Perfil público</label></div><div class="form-actions"><Link class="button button--outline-small" :href="route('admin.doctors.index')">Cancelar</Link><button class="button button--admin" :disabled="form.processing">{{ form.processing?'Guardando...':'Guardar médico' }}</button></div></form></template>
